<?php namespace Veltrion\Services\Commercial\Protection; require_once __DIR__ . '/Contracts/ProtectionProviderInterface.php'; use Veltrion\Services\Commercial\Protection\Contracts\ProtectionProviderInterface; class NativeProtectionProvider implements ProtectionProviderInterface { public function getName(): string { return 'Veltrion Native PHP Minifier & Guard Encoder'; } public function isAvailable(): bool { return true; } public function protectDirectory(string $sourceDir, string $targetDir, array $options = []): array { if (!is_dir($targetDir)) { mkdir($targetDir, 0777, true); } $processed = 0; $protectedFiles = []; $excludedPaths = array_merge($options['excluded'] ?? ['.env', '.git', 'storage'], ['storage', 'vendor']); $realSource = realpath($sourceDir) ?: $sourceDir; $realTarget = realpath($targetDir) ?: $targetDir; $iterator = new \RecursiveIteratorIterator( new \RecursiveDirectoryIterator($sourceDir, \RecursiveDirectoryIterator::SKIP_DOTS), \RecursiveIteratorIterator::SELF_FIRST ); foreach ($iterator as $item) { $itemPath = $item->getPathname(); $realItem = realpath($itemPath) ?: $itemPath; if ($realTarget && str_starts_with($realItem, $realTarget)) { continue; } $relPath = str_replace($sourceDir . '/', '', $itemPath); $skip = false; foreach ($excludedPaths as $ex) { if (str_contains($relPath, $ex)) { $skip = true; break; } } if ($skip) continue; $destPath = $targetDir . '/' . $relPath; if ($item->isDir()) { if (!is_dir($destPath)) { @mkdir($destPath, 0777, true); } } else if ($item->isFile()) { $dir = dirname($destPath); if (!is_dir($dir)) { @mkdir($dir, 0777, true); } if ($item->getExtension() === 'php') { $code = file_get_contents($item->getPathname()); $protectedCode = $this->protectPhpCode($code, $options); file_put_contents($destPath, $protectedCode); $protectedFiles[] = $relPath; $processed++; } else { @copy($item->getPathname(), $destPath); } } } $manifest = [ 'provider' => $this->getName(), 'version' => '1.0.0', 'timestamp' => date('Y-m-d H:i:s'), 'processed_files_count' => $processed, 'protected_paths' => array_slice($protectedFiles, 0, 50), 'options' => $options ]; file_put_contents($targetDir . '/protection-manifest.json', json_encode($manifest, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE)); return [ 'success' => true, 'provider' => $this->getName(), 'files_processed' => $processed, 'manifest_path' => $targetDir . '/protection-manifest.json' ]; } private function protectPhpCode(string $code, array $options): string { $stripped = @php_strip_whitespace_str($code); if (!$stripped) { $stripped = $code; } if (!str_contains($stripped, 'VELTRION_PROTECTION_GUARD')) { $guard = "<?php\n/* VELTRION_PROTECTION_GUARD v1.0 | Commercial Build Protection */\n" . "if(!defined('VELTRION_RUNTIME_GUARD') && file_exists(__DIR__ . '/../bootstrap/guard.php')){ @include_once __DIR__ . '/../bootstrap/guard.php'; }\n"; $stripped = preg_replace('/^\s*<\?php/i', $guard, $stripped, 1); } return $stripped; } } if (!function_exists('php_strip_whitespace_str')) { function php_strip_whitespace_str(string $code): string { $tokens = token_get_all($code); $output = ''; foreach ($tokens as $token) { if (is_string($token)) { $output .= $token; } else { list($id, $text) = $token; switch ($id) { case T_COMMENT: case T_DOC_COMMENT: break; case T_WHITESPACE: $output .= ' '; break; default: $output .= $text; break; } } } return preg_replace('/\s+/', ' ', $output); } } 